#include <iostream>
using namespace std;

int main() {
    long long num;
    cin >> num;

    if (num < 1 || num > 1000000000LL) {
        cout << "error\n";
        return 0;
    }

    int result = 0;
    int placeValue = 1;

    while (num > 0) {
        int digit = num % 10;

        if (digit != 0 && digit != 1) {
            cout << "error\n";
            return 0;
        }

        result += digit * placeValue;
        placeValue *= 2;
        num /= 10;
    }

    cout << result << '\n';
    return 0;
}

#include <iostream>
