using namespace std;

int main() {
    long long num;
    cin >> num;

    if (num < 1 || num > 1000000000LL) {
        cout << "error\n";
        return 0;
    }

    string s = to_string(num);
    int result = 0;

    for (size_t i = 0; i < s.size(); ++i) {
        int digit = s[i] - '0';

        if (digit <= 1) {
            result = result * 2 + digit;
        } else {
            result = result * 2 + 1;
            for (++i; i < s.size(); ++i)
                result = result * 2 + 1;
            break;
        }
    }

    cout << result << '\n';
    return 0;
}

