int main() {
    long long num;
    cin >> num;

    if (num < 1 || num > 1000000000LL) {
        cout << "error\n";
        return 0;
    }

    int result = 0;

    for (int mask = 1; mask < (1 << 10); ++mask) {
        long long value = 0;
        int bits = mask;

        while (bits > 0) {
            value = value * 10 + (bits & 1);
            bits >>= 1;
        }

        if (value <= num)
            ++result;
    }

    cout << result << '\n';
    return 0;
}

